import pathlib,json,hashlib,zipfile
root=pathlib.Path('products/invoice-preflight'); out=pathlib.Path('products/distribution'); out.mkdir(parents=True,exist_ok=True)
files=sorted(p for p in root.rglob('*') if p.is_file() and not p.is_symlink())
if not files: raise SystemExit('No product files found; bundle not created')
manifest={'files':[{'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in files],'claims':{'publicly_deployed':False,'payment_available':False,'real_platform_import_verified':False},'review_status':'Independent review of this exact bundle is required before public listing.'}
archive=out/'invoice-preflight-review.zip'
with zipfile.ZipFile(archive,'w',zipfile.ZIP_DEFLATED) as z:
 for p in files: z.write(p,p.relative_to(root))
with zipfile.ZipFile(archive) as z:
 bad=z.testzip()
 if bad: raise SystemExit('Archive verification failed: '+bad)
manifest['archive_sha256']=hashlib.sha256(archive.read_bytes()).hexdigest(); manifest['archive_integrity_checked']=True
p=out/'bundle-manifest.json'; p.write_text(json.dumps(manifest,indent=2)); print(p.read_text())
